from lib import R
F = "68-vegetarian-vegan-mains.txt"
D = "Lunch, Dinner, Main dish"
L = [
 ("Lentil Shepherd's Pie", "British", 20, 45, 6, "300 g|green lentils; 1|onion, chopped; 2|carrots, diced; 2 stalks|celery, diced; 2 tbsp|tomato paste; 1 tbsp|soy sauce; 500 ml|vegetable stock; 1 kg|potatoes, peeled; 60 g|butter; 100 ml|milk; 2 tbsp|olive oil; |salt", "Boil the potatoes until tender and mash with the butter, milk and salt / Cook the onion, carrots and celery in the oil for 8 minutes, add the tomato paste, lentils, soy and stock and simmer for 25 minutes until thick / Spread the lentils in a dish, top with mash and bake at 200 °C (400 °F) for 20 minutes until golden"),
 ("Eggplant Parmesan", "Italian-American", 30, 40, 6, "2|eggplants, sliced 1 cm thick; 100 g|flour; 2|eggs, beaten; 150 g|breadcrumbs; 700 g|marinara sauce; 250 g|mozzarella; 60 g|parmesan; 1 handful|basil; 6 tbsp|olive oil; |salt", "Salt the eggplant for 20 minutes and pat dry / Dip in flour, egg and breadcrumbs and fry in the oil until golden, or brush with oil and bake at 220 °C for 20 minutes / Layer with marinara, mozzarella, parmesan and basil in a dish and bake at 190 °C (375 °F) for 25 minutes"),
 ("Black Bean Burgers", "American", 20, 15, 4, "2 can|black beans, drained and dried; 50 g|breadcrumbs; 1|egg; 0.5|onion, grated; 1 tsp|cumin; 1 tsp|smoked paprika; 2 tbsp|vegetable oil; 4|burger buns; 1|avocado; |salt", "Mash the beans roughly, leaving some whole / Mix with the breadcrumbs, egg, onion, spices and salt and shape 4 patties; chill 15 minutes / Fry in the oil for 4 to 5 minutes per side and serve in buns with avocado"),
 ("Chickpea Tikka Masala", "Indian", 10, 30, 4, "2 can|chickpeas, drained; 1|onion, chopped; 3 cloves|garlic; 1 tbsp|ginger; 2 tbsp|tikka masala paste; 1 can|canned tomatoes; 200 ml|coconut milk; 2 tbsp|vegetable oil; 1 handful|cilantro; |salt", "Cook the onion in the oil for 8 minutes, then the garlic, ginger and paste for 1 minute / Add the tomatoes and simmer 10 minutes, then blend if you like it smooth / Add the chickpeas and coconut milk and simmer 10 minutes; finish with cilantro"),
 ("Vegetable Lasagna", "Italian", 30, 50, 8, "12|lasagna sheets; 2|zucchini, diced; 1|eggplant, diced; 2|red bell peppers, diced; 700 g|marinara sauce; 500 g|ricotta; 250 g|mozzarella; 60 g|parmesan; 3 tbsp|olive oil; |salt", "Roast the vegetables with the oil and salt at 220 °C (425 °F) for 25 minutes and stir into the marinara / Layer sauce, lasagna sheets, ricotta and mozzarella three times, ending with sauce and parmesan / Cover with foil and bake at 190 °C for 30 minutes, uncover for 15 minutes and rest 10 minutes"),
 ("Mushroom Stroganoff", "Russian", 10, 20, 4, "600 g|mushrooms, sliced; 1|onion, sliced; 2 cloves|garlic; 1 tsp|paprika; 250 ml|vegetable stock; 150 g|sour cream; 1 tbsp|dijon mustard; 300 g|egg noodles; 2 tbsp|butter; 1 handful|parsley; |salt", "Cook the noodles and drain / Brown the mushrooms in the butter in batches, then cook the onion and garlic for 5 minutes / Add the paprika and stock and simmer 5 minutes, then stir in the sour cream and mustard off the heat and serve over the noodles with parsley"),
 ("Stuffed Bell Peppers with Rice and Beans", "Mexican", 20, 40, 4, "4|bell peppers, tops cut off; 200 g|long-grain rice, cooked; 1 can|black beans, drained; 200 g|sweetcorn; 200 g|salsa; 1 tsp|cumin; 120 g|cheddar, grated; |salt", "Heat the oven to 190 °C (375 °F) / Mix the rice, beans, corn, salsa, cumin and half the cheese and fill the peppers / Stand them in a dish with 4 tbsp water, cover and bake 30 minutes, then uncover, add the cheese and bake 10 minutes"),
 ("Spinach and Ricotta Cannelloni", "Italian", 25, 35, 6, "250 g|cannelloni tubes; 500 g|ricotta; 300 g|spinach, cooked and squeezed; 1|egg; 60 g|parmesan; 0.25 tsp|nutmeg; 700 g|marinara sauce; 150 g|mozzarella; |salt", "Heat the oven to 190 °C (375 °F) / Mix the ricotta, spinach, egg, half the parmesan, nutmeg and salt and pipe into the tubes / Lay on half the sauce, cover with the rest, top with cheeses and bake covered 25 minutes, then uncovered 10 minutes"),
 ("Vegan Chili sin Carne", "Tex-Mex", 15, 40, 6, "1|onion, chopped; 1|red bell pepper, diced; 3 cloves|garlic; 2 tbsp|chili powder; 1 tsp|cumin; 1 tsp|smoked paprika; 2 can|kidney beans, drained; 1 can|black beans, drained; 2 can|canned tomatoes; 150 g|bulgur wheat; 500 ml|vegetable stock; 2 tbsp|olive oil; |salt", "Cook the onion and pepper in the oil for 8 minutes, then the garlic and spices for 1 minute / Add the beans, tomatoes, bulgur and stock / Simmer for 30 minutes, stirring often, until thick; season well"),
 ("Cauliflower Steaks with Romesco", "Spanish", 10, 25, 4, "2|cauliflower heads, cut into thick slices; 3 tbsp|olive oil; 1 tsp|smoked paprika; 200 g|romesco sauce; 1 handful|parsley; |salt", "Heat the oven to 220 °C (425 °F) / Brush the cauliflower slices with the oil, paprika and salt and sear in a hot pan for 2 minutes per side / Roast for 18 to 20 minutes until tender and serve on romesco with parsley"),
 ("Halloumi and Vegetable Skewers", "Cypriot", 20, 12, 4, "250 g|halloumi, cubed; 1|zucchini, in chunks; 1|red onion, in chunks; 1|red bell pepper, in chunks; 200 g|cherry tomatoes; 3 tbsp|olive oil; 1 tsp|dried oregano; 1|lemon", "Thread the halloumi and vegetables onto skewers / Brush with the oil and oregano / Grill or griddle for 10 to 12 minutes, turning, and squeeze over the lemon"),
 ("Spanakopita Pie", "Greek", 25, 45, 8, "500 g|spinach, wilted and squeezed; 200 g|feta, crumbled; 1 bunch|green onions; 1 handful|dill; 2|eggs; 10 sheets|phyllo dough; 100 g|butter, melted; |black pepper", "Heat the oven to 180 °C (350 °F) / Mix the spinach, feta, onions, dill, eggs and pepper / Layer half the phyllo in a dish, brushing each sheet with butter, add the filling, top with the rest, score and bake for 40 to 45 minutes"),
 ("Tofu Katsu", "Japanese", 15, 15, 4, "400 g|firm tofu, pressed and sliced; 60 g|flour; 2|eggs, beaten; 100 g|panko; 6 tbsp|vegetable oil; 4 tbsp|tonkatsu sauce; 200 g|cabbage, finely shredded; 300 g|short-grain rice, cooked", "Coat the tofu in flour, egg and panko / Fry in the oil for 3 minutes per side until golden and drain / Slice and serve with rice, cabbage and tonkatsu sauce"),
 ("Sweet Potato and Chickpea Buddha Traybake", "Middle Eastern", 10, 30, 4, "2|sweet potatoes, cubed; 1 can|chickpeas, drained; 1|red onion, wedged; 1 tsp|cumin; 1 tsp|smoked paprika; 3 tbsp|olive oil; 100 g|spinach; 4 tbsp|tahini sauce; |salt", "Heat the oven to 220 °C (425 °F) / Toss the sweet potato, chickpeas and onion with the oil, spices and salt and roast for 30 minutes / Toss with the spinach to wilt and drizzle with tahini sauce"),
 ("Pasta alla Norma", "Italian", 15, 30, 4, "2|eggplants, cubed; 6 tbsp|olive oil; 3 cloves|garlic; 1 can|canned tomatoes; 400 g|rigatoni; 1 handful|basil; 60 g|ricotta salata, grated; |salt", "Fry the eggplant in the oil until golden and soft, about 12 minutes, and set aside / Cook the garlic briefly, add the tomatoes and simmer 15 minutes, then return the eggplant / Toss with the cooked rigatoni and basil and top with ricotta salata"),
 ("Vegetable Paella", "Spanish", 15, 35, 4, "300 g|paella rice; 1|onion, chopped; 1|red bell pepper, sliced; 150 g|green beans; 1 can|artichoke hearts; 150 g|peas; 1 pinch|saffron; 1 tsp|smoked paprika; 900 ml|vegetable stock; 4 tbsp|olive oil; 1|lemon; |salt", "Cook the onion, pepper and beans in the oil in a wide pan for 6 minutes / Stir in the paprika and rice, then the saffron and hot stock; spread evenly and do not stir again / Simmer 18 minutes, add the artichokes and peas, cook 5 minutes more, then rest 5 minutes off the heat with lemon"),
 ("Mushroom Bourguignon", "French", 15, 40, 4, "800 g|mushrooms, halved; 200 g|pearl onions, peeled; 2|carrots, sliced; 3 cloves|garlic; 2 tbsp|tomato paste; 2 tbsp|flour; 300 ml|red wine; 300 ml|vegetable stock; 2 sprigs|thyme; 3 tbsp|olive oil; |salt", "Brown the mushrooms in the oil in batches / Cook the onions, carrots and garlic for 5 minutes, then the tomato paste and flour for 1 minute / Add the wine, stock, thyme and mushrooms and simmer 30 minutes until glossy; serve with mash"),
 ("Saag Paneer", "Indian", 15, 25, 4, "250 g|paneer, cubed; 500 g|spinach; 1|onion, chopped; 3 cloves|garlic; 1 tbsp|ginger; 1|green chili; 1 tsp|garam masala; 1 tsp|cumin; 4 tbsp|heavy cream; 2 tbsp|ghee; |salt", "Brown the paneer in half the ghee and set aside / Wilt the spinach and blend to a coarse puree / Cook the onion in the rest of the ghee for 8 minutes, add the garlic, ginger, chili and spices, then the spinach and cream; simmer 5 minutes and fold in the paneer"),
 ("Mapo Tofu with Mushrooms", "Chinese", 10, 15, 4, "400 g|silken tofu, cubed; 200 g|shiitake mushrooms, finely chopped; 2 tbsp|doubanjiang; 1 tsp|sichuan peppercorns, ground; 3 cloves|garlic; 1 tbsp|ginger; 250 ml|vegetable stock; 1 tbsp|soy sauce; 1 tbsp|cornstarch; 2 tbsp|vegetable oil; 2|green onions", "Fry the mushrooms in the oil until browned, then the doubanjiang, garlic and ginger for 1 minute / Add the stock, soy and tofu and simmer gently 5 minutes / Thicken with the cornstarch mixed with water and finish with the peppercorns and green onions"),
 ("Butternut Squash Risotto", "Italian", 15, 35, 4, "300 g|arborio rice; 500 g|butternut squash, small dice; 1|onion, chopped; 120 ml|dry white wine; 1.2 l|vegetable stock, hot; 50 g|parmesan; 2 tbsp|butter; 6|sage leaves; 2 tbsp|olive oil; |salt", "Roast the squash with the oil at 200 °C for 25 minutes / Cook the onion in half the butter, stir in the rice, add the wine, then the stock a ladle at a time, stirring, for 18 to 20 minutes / Fold in the squash, parmesan and the rest of the butter; fry the sage leaves briefly for topping"),
 ("Black Bean Enchiladas", "Mexican", 20, 25, 4, "2 can|black beans, drained; 200 g|sweetcorn; 1 tsp|cumin; 8|corn tortillas; 500 ml|enchilada sauce; 150 g|cheddar, grated; 1 handful|cilantro; 4 tbsp|sour cream", "Heat the oven to 190 °C (375 °F) / Mash half the beans and mix with the rest, the corn, cumin and a third of the cheese / Fill and roll the warmed tortillas, lay in a dish over a little sauce, pour over the rest and top with cheese / Bake 20 to 25 minutes and top with cilantro and sour cream"),
 ("Thai Red Curry Noodle Soup with Tofu", "Thai", 10, 20, 4, "2 tbsp|red curry paste; 1 can|coconut milk; 750 ml|vegetable stock; 200 g|rice noodles; 300 g|firm tofu, cubed; 150 g|mushrooms, sliced; 100 g|bok choy; 1 tbsp|soy sauce; 1|lime; 1 handful|thai basil; 1 tbsp|vegetable oil", "Fry the curry paste in the oil for 1 minute / Add the coconut milk, stock, soy, tofu and mushrooms and simmer 10 minutes / Add the bok choy for 2 minutes, then pour over the cooked noodles with lime and basil"),
 ("Gnocchi with Brown Butter and Sage", "Italian", 5, 10, 4, "500 g|potato gnocchi; 80 g|butter; 12|sage leaves; 40 g|parmesan; 1|lemon, zested; |black pepper", "Boil the gnocchi until they float and drain / Cook the butter and sage in a wide pan until nutty brown / Toss in the gnocchi for 2 minutes and finish with parmesan, lemon zest and pepper"),
 ("Zucchini Fritters with Yogurt Sauce", "Turkish", 20, 15, 4, "3|zucchini, grated and squeezed; 2|eggs; 60 g|flour; 100 g|feta, crumbled; 3|green onions; 1 handful|dill; 4 tbsp|vegetable oil; 200 g|yogurt; 1 clove|garlic; |salt", "Mix the zucchini, eggs, flour, feta, onions, dill and pepper / Fry spoonfuls in the oil for 3 minutes per side until golden / Serve with the yogurt mixed with garlic and salt"),
 ("Moroccan Vegetable Tagine", "Moroccan", 20, 40, 6, "1|onion, chopped; 2|carrots, chunked; 1|sweet potato, cubed; 1|zucchini, chunked; 1 can|chickpeas, drained; 1 can|canned tomatoes; 60 g|dried apricots; 2 tsp|ras el hanout; 1 tsp|cinnamon; 500 ml|vegetable stock; 3 tbsp|olive oil; 1 handful|cilantro; 250 g|couscous", "Cook the onion in the oil for 6 minutes, then the spices for 1 minute / Add the vegetables except the zucchini, chickpeas, tomatoes, apricots and stock and simmer covered 25 minutes / Add the zucchini for 10 minutes and serve over couscous with cilantro"),
 ("Tofu Pad Thai", "Thai", 20, 10, 4, "250 g|rice noodles; 300 g|firm tofu, cubed; 2|eggs; 100 g|bean sprouts; 3|green onions; 3 tbsp|tamarind; 2 tbsp|fish sauce; 2 tbsp|brown sugar; 3 tbsp|vegetable oil; 50 g|peanuts, chopped; 1|lime", "Soak the noodles in hot water until pliable and drain / Fry the tofu in the oil until golden, push aside and scramble the eggs / Add the noodles with the tamarind, fish sauce and sugar and toss for 2 minutes, then the sprouts and onions / Serve with peanuts and lime; use soy sauce for a vegetarian version"),
 ("Vegan Mushroom Lentil Bolognese", "Italian", 15, 35, 4, "250 g|mushrooms, finely chopped; 150 g|red lentils; 1|onion; 1|carrot; 1 stalk|celery; 3 cloves|garlic; 2 tbsp|tomato paste; 1 can|canned tomatoes; 400 ml|vegetable stock; 400 g|spaghetti; 3 tbsp|olive oil; |salt", "Finely chop the onion, carrot and celery and cook in the oil for 10 minutes with the mushrooms / Add the garlic and tomato paste, then the lentils, tomatoes and stock and simmer 25 minutes / Toss with the cooked spaghetti"),
 ("Cheese and Onion Pasties", "British", 30, 30, 6, "500 g|shortcrust pastry; 300 g|potatoes, small dice; 1|onion, finely chopped; 200 g|cheddar, grated; 1|egg, beaten; |salt; |black pepper", "Heat the oven to 200 °C (400 °F) / Boil the potatoes for 5 minutes, drain and cool, then mix with the onion, cheese, salt and pepper / Cut 6 pastry circles, fill, fold and crimp / Brush with egg and bake 25 to 30 minutes"),
 ("Korean Tofu Stew (Sundubu Jjigae)", "Korean", 10, 20, 4, "400 g|silken tofu; 150 g|kimchi, chopped; 2 tbsp|gochugaru; 1 tbsp|soy sauce; 3 cloves|garlic; 100 g|mushrooms, sliced; 750 ml|vegetable stock; 4|eggs; 2|green onions; 1 tbsp|sesame oil", "Fry the kimchi, garlic and gochugaru in the sesame oil for 2 minutes / Add the stock, soy and mushrooms and simmer 10 minutes / Spoon in the tofu in large pieces, crack in the eggs and simmer 3 minutes; top with green onions"),
 ("Polenta with Mushroom Ragout", "Italian", 10, 30, 4, "200 g|polenta; 1 l|water; 40 g|parmesan; 2 tbsp|butter; 500 g|mushrooms, sliced; 2 cloves|garlic; 1 tsp|dried thyme; 120 ml|dry white wine; 2 tbsp|olive oil; |salt", "Whisk the polenta into the boiling salted water and cook, stirring often, for 25 to 30 minutes; finish with parmesan and butter / Brown the mushrooms in the oil, add the garlic and thyme, then the wine and reduce / Serve the ragout over the polenta"),
 ("Sweet Potato and Black Bean Quesadillas", "Mexican", 10, 20, 4, "1|sweet potato, cooked and mashed; 1 can|black beans, drained; 1 tsp|cumin; 150 g|cheddar, grated; 4|flour tortillas; 150 g|salsa", "Mix the sweet potato, beans and cumin / Spread on half of each tortilla, top with cheese and fold / Toast in a dry pan for 3 minutes per side and serve with salsa"),
 ("Egg Fried Rice with Vegetables", "Chinese", 10, 10, 4, "600 g|long-grain rice, cooked and cold; 3|eggs; 150 g|peas; 1|carrot, diced; 3|green onions; 3 tbsp|soy sauce; 1 tsp|sesame oil; 3 tbsp|vegetable oil", "Scramble the eggs in 1 tbsp oil and set aside / Stir-fry the carrot and peas in the rest of the oil for 3 minutes, add the rice and fry until hot and slightly crisp / Add the soy, eggs, green onions and sesame oil and toss"),
 ("Kimchi Fried Rice", "Korean", 10, 10, 2, "400 g|short-grain rice, cooked and cold; 150 g|kimchi, chopped; 2 tbsp|kimchi juice; 1 tbsp|gochujang; 1 tbsp|butter; 2|eggs; 2|green onions; 1 tsp|sesame oil", "Fry the kimchi in the butter for 3 minutes / Add the rice, kimchi juice and gochujang and fry until hot / Top with fried eggs, green onions and sesame oil"),
 ("Crispy Tofu with Sweet Chili Glaze", "Thai", 15, 15, 4, "400 g|firm tofu, pressed and cubed; 2 tbsp|cornstarch; 4 tbsp|vegetable oil; 4 tbsp|sweet chili sauce; 1 tbsp|soy sauce; 1|lime; 2|green onions", "Toss the tofu in the cornstarch and fry in the oil until crisp on all sides, about 10 minutes / Add the sweet chili sauce and soy and toss to glaze / Finish with lime and green onions and serve with rice"),
 ("Lentil and Vegetable Moussaka", "Greek", 30, 50, 6, "2|eggplants, sliced; 200 g|green lentils, cooked; 1|onion, chopped; 2 cloves|garlic; 1 can|canned tomatoes; 1 tsp|cinnamon; 500 ml|bechamel sauce; 60 g|parmesan; 4 tbsp|olive oil; |salt", "Brush the eggplant with oil and roast at 220 °C for 20 minutes / Cook the onion and garlic, add the lentils, tomatoes and cinnamon and simmer 15 minutes / Layer eggplant and lentils in a dish, top with bechamel and parmesan and bake at 180 °C (350 °F) for 30 minutes"),
 ("Paneer Butter Masala", "Indian", 15, 25, 4, "300 g|paneer, cubed; 1|onion, chopped; 3 cloves|garlic; 1 tbsp|ginger; 1 can|canned tomatoes; 40 g|cashews; 1 tsp|garam masala; 1 tsp|Kashmiri chili powder; 3 tbsp|butter; 100 ml|heavy cream; 1 tsp|sugar; |salt", "Cook the onion, garlic and ginger in the butter for 8 minutes, add the tomatoes and cashews and simmer 10 minutes / Blend until smooth and return to the pan with the spices, sugar and cream / Add the paneer and simmer 5 minutes"),
 ("Vegan Coconut Chickpea Stew with Kale", "Caribbean", 10, 25, 4, "2 can|chickpeas, drained; 1 can|coconut milk; 1|onion, chopped; 3 cloves|garlic; 1 tbsp|ginger; 1 tsp|turmeric; 1 tsp|cumin; 150 g|kale, chopped; 1|lime; 2 tbsp|olive oil; |salt", "Cook the onion in the oil for 6 minutes, add the garlic, ginger and spices for 1 minute / Add the chickpeas and coconut milk with 200 ml water and simmer 15 minutes, mashing a few chickpeas / Stir in the kale until wilted and finish with lime"),
 ("Tempeh Bacon BLT", "American", 10, 10, 2, "200 g|tempeh, thinly sliced; 2 tbsp|soy sauce; 1 tbsp|maple syrup; 1 tsp|smoked paprika; 4 slices|bread, toasted; 2|tomatoes, sliced; 1 handful|lettuce; 2 tbsp|vegan mayonnaise; 2 tbsp|vegetable oil", "Marinate the tempeh in the soy, maple and paprika for 10 minutes / Fry in the oil for 3 minutes per side until crisp / Build sandwiches with mayonnaise, lettuce, tomato and tempeh"),
 ("Mushroom and Leek Pie", "British", 25, 40, 6, "500 g|mushrooms, sliced; 2|leeks, sliced; 2 tbsp|butter; 2 tbsp|flour; 300 ml|milk; 1 tsp|dried thyme; 1 tbsp|dijon mustard; 1 sheet|puff pastry; 1|egg, beaten; |salt", "Cook the leeks and mushrooms in the butter for 10 minutes / Stir in the flour, then the milk, thyme and mustard and simmer until thick; season and cool slightly / Pour into a pie dish, cover with the pastry, brush with egg and bake at 200 °C (400 °F) for 25 to 30 minutes"),
 ("Quinoa Stuffed Acorn Squash", "American", 15, 45, 4, "2|acorn squash, halved and seeded; 150 g|quinoa, cooked; 60 g|dried cranberries; 60 g|pecans, chopped; 1|apple, diced; 100 g|spinach; 2 tbsp|maple syrup; 2 tbsp|olive oil; |salt", "Heat the oven to 200 °C (400 °F) / Brush the squash with oil and roast cut-side down for 30 minutes / Mix the quinoa, cranberries, pecans, apple, spinach and maple syrup, fill the squash and bake 15 minutes more"),
 ("Vegetable Biryani", "Indian", 25, 40, 6, "350 g|basmati rice; 1|onion, sliced; 2|carrots, diced; 150 g|green beans, cut; 150 g|cauliflower, small florets; 150 g|peas; 150 g|yogurt; 2 tbsp|biryani masala; 1 pinch|saffron; 3 tbsp|ghee; 1 handful|mint; 1 handful|cilantro; |salt", "Par-boil the rice for 5 minutes and drain / Fry the onion in the ghee until golden, add the vegetables, masala and yogurt and cook 8 minutes / Layer the rice over the vegetables with the herbs and saffron soaked in 3 tbsp warm milk or water, cover tightly and cook on low for 25 minutes"),
 ("Vegan Shepherd's Pie with Mushrooms", "British", 20, 45, 6, "500 g|mushrooms, chopped; 200 g|green lentils, cooked; 1|onion; 2|carrots; 150 g|peas; 2 tbsp|tomato paste; 1 tbsp|soy sauce; 300 ml|vegetable stock; 1 kg|potatoes; 3 tbsp|olive oil; 100 ml|oat milk; |salt", "Boil and mash the potatoes with 2 tbsp oil and the oat milk / Cook the chopped onion, carrots and mushrooms in the rest of the oil for 10 minutes, add the tomato paste, soy, lentils, peas and stock and simmer 15 minutes / Top with the mash and bake at 200 °C (400 °F) for 20 minutes"),
 ("Huevos a la Flamenca", "Spanish", 10, 25, 4, "1|onion, chopped; 2|red bell peppers, sliced; 2 cloves|garlic; 1 tsp|smoked paprika; 1 can|canned tomatoes; 150 g|peas; 4|eggs; 3 tbsp|olive oil; |salt", "Cook the onion and peppers in the oil for 10 minutes, then the garlic and paprika / Add the tomatoes and peas and simmer 10 minutes / Make wells, crack in the eggs, cover and cook 5 to 6 minutes until the whites set"),
 ("Cauliflower Mac and Cheese", "American", 15, 30, 6, "300 g|macaroni; 1|cauliflower, in small florets; 3 tbsp|butter; 3 tbsp|flour; 600 ml|milk; 200 g|cheddar, grated; 1 tsp|dijon mustard; 40 g|breadcrumbs; |salt", "Cook the macaroni, adding the cauliflower for the last 5 minutes, and drain / Make a sauce with the butter, flour and milk, then melt in the cheese and mustard / Combine, tip into a dish, top with breadcrumbs and bake at 200 °C (400 °F) for 15 minutes"),
 ("Peanut Noodle Stir-Fry with Tofu", "Thai", 15, 15, 4, "250 g|rice noodles; 300 g|firm tofu, cubed; 1|red bell pepper, sliced; 150 g|snow peas; 1|carrot, julienned; 4 tbsp|peanut butter; 3 tbsp|soy sauce; 1 tbsp|maple syrup; 1|lime; 2 tbsp|vegetable oil", "Soak or cook the noodles and drain / Fry the tofu in the oil until golden, add the vegetables and stir-fry 3 minutes / Whisk the peanut butter, soy, maple and lime with 4 tbsp hot water and toss everything together"),
 ("Bean and Cheese Burritos", "Mexican", 10, 10, 4, "2 can|pinto beans, drained; 1 tsp|cumin; 1 tsp|chili powder; 200 g|long-grain rice, cooked; 150 g|cheddar, grated; 4|flour tortillas; 150 g|salsa; 1 tbsp|vegetable oil", "Mash the beans with the spices and a splash of water in a pan over low heat / Fill the tortillas with beans, rice, cheese and salsa and roll / Toast seam-side down in the oiled pan until golden"),
]
for t, cu, p, c, s, ings, steps in L:
    R(F, t, "Main", cu, p, c, s, D, ings, steps)
